// Synthetic authoritative-result persistence tests; no campaign scoring formula.
#include "server/crusades/store.h"
#include <sqlite3.h>
#include <chrono>
#include <filesystem>
#include <iostream>
#include <limits>
#include <set>
#include <stdexcept>
namespace c=tak::srv::crusades;
namespace fs=std::filesystem;
namespace {
int checks=0;
void check(bool b,const char* m){++checks;if(!b)throw std::runtime_error(m);}
template<class F>void rejects(F f,const char* m){++checks;try{f();}catch(const std::runtime_error&){return;}throw std::runtime_error(m);}
c::BattleContext context(){return {"one.ota",std::string(64,'a'),std::string(64,'b'),{"alice","bob"},true};}
void seed(c::CampaignStore& s){auto d=c::loadDefinitionText("campaign 1 \"test\" \"Test\"\nterritory 1 \"One\"\nmap 1 \"one.ota\"\n");s.create(d,c::makeInitialState(d),"initial");s.setAllegiance("test","alice",c::Alliance::Honor,-1,1);s.setAllegiance("test","bob",c::Alliance::Terror,-1,1);}
c::IssuedBattle started(c::CampaignStore& s,const std::string& room){auto b=s.issueBattle("test",s.load("test").revision,1,context(),10,20);s.startBattle(b.id,b.launchToken,room,context(),11);return b;}
c::VerifiedMatchResult result(const std::string& replay="replay-one"){
 c::VerifiedMatchResult r;r.outcome=c::ResultOutcome::Victory;r.winners={"alice"};r.finalTick=1234;r.finalStateHash=UINT64_MAX;r.gameplayFingerprint=UINT64_C(0x8000000000000001);r.engineBuild="test-build";r.replayId=replay;r.replayDigest=std::string(64,'c');
 r.participantResults={{"bob",1,2,-7,3,0,"Taros",1,true},{"alice",2,1,99,4,3,"Aramon",0,false}};return r;
}
struct Raw{sqlite3* db=nullptr;explicit Raw(const fs::path& p){auto bytes=p.u8string();if(sqlite3_open(reinterpret_cast<const char*>(bytes.c_str()),&db)!=SQLITE_OK)throw std::runtime_error("raw open");}~Raw(){sqlite3_close(db);}void sql(const std::string& s){char* e=nullptr;if(sqlite3_exec(db,s.c_str(),nullptr,nullptr,&e)!=SQLITE_OK){std::string m=e?e:"SQL";sqlite3_free(e);throw std::runtime_error(m);}}int64_t count(const char* s){sqlite3_stmt* q=nullptr;if(sqlite3_prepare_v2(db,s,-1,&q,nullptr)!=SQLITE_OK)throw std::runtime_error("prepare");int rc=sqlite3_step(q);auto n=sqlite3_column_int64(q,0);sqlite3_finalize(q);if(rc!=SQLITE_ROW)throw std::runtime_error("row");return n;}};
void validation(){c::CampaignStore s(":memory:");seed(s);auto b=started(s,"room");auto good=result();
 rejects([&]{s.recordVerifiedResult("ordinary","room",context(),good,12);},"unknown battle accepted");
 rejects([&]{s.recordVerifiedResult(b.id,"wrong",context(),good,12);},"wrong room accepted");
 rejects([&]{s.recordVerifiedResult(b.id,"room",context(),good,10);},"time reversal accepted");
 for(int n=0;n<5;++n){auto x=context();if(n==0)x.mapIdentifier="other";if(n==1)x.mapDigest="other";if(n==2)x.rulesDigest="other";if(n==3)x.participants={"alice","other"};if(n==4)x.crusadesBalance=false;rejects([&]{s.recordVerifiedResult(b.id,"room",x,good,12);},"context substitution accepted");}
 for(int n=0;n<25;++n){auto x=good;switch(n){case 0:x.outcome=static_cast<c::ResultOutcome>(99);break;case 1:x.winners.clear();break;case 2:x.winners={"bob","alice"};break;case 3:x.winners={"unknown"};break;case 4:x.finalTick=0;break;case 5:x.replayId.clear();break;case 6:x.replayDigest.clear();break;case 7:x.replayDigest=std::string(64,'Z');break;case 8:x.replayDigest=std::string(63,'a');break;case 9:x.engineBuild.clear();break;case 10:x.engineBuild=std::string(257,'a');break;case 11:x.participantResults.pop_back();break;case 12:x.participantResults[0].accountId="alice";break;case 13:x.participantResults[0].accountId="Bob";break;case 14:x.participantResults[0].kills=-1;break;case 15:x.participantResults[0].losses=-1;break;case 16:x.participantResults[0].built=-1;break;case 17:x.participantResults[0].currentUnits=-1;break;case 18:x.participantResults[0].faction.clear();break;case 19:x.participantResults[0].team=-1;break;case 20:x.participantResults[0].defeated=false;break;case 21:x.participantResults[1].defeated=true;break;case 22:x.participantResults[0].team=0;break;case 23:x.outcome=c::ResultOutcome::Desync;break;case 24:x.participantResults[0].faction=std::string(257,'a');break;}
 rejects([&]{s.recordVerifiedResult(b.id,"room",context(),x,12);},"invalid result accepted");check(!s.verifiedResult(b.id)&&s.battle(b.id).status==c::BattleStatus::Started,"invalid result partially committed");}
 s.recordVerifiedResult(b.id,"room",context(),good,30);auto saved=s.verifiedResult(b.id);check(saved&&saved->finalStateHash==UINT64_MAX&&saved->gameplayFingerprint==good.gameplayFingerprint,"uint64 hashes lost precision");check(saved->participantResults[0].accountId=="alice"&&saved->participantResults[1].score==-7,"canonical stats or signed score lost");check(s.battle(b.id).status==c::BattleStatus::Completed,"result missing completed status");
 rejects([&]{s.recordVerifiedResult(b.id,"room",context(),good,31);},"duplicate result accepted");good.finalStateHash=123;rejects([&]{s.recordVerifiedResult(b.id,"room",context(),good,31);},"altered hash replacement accepted");check(s.verifiedResult(b.id)->finalStateHash==UINT64_MAX,"duplicate changed hash");
 auto second=started(s,"room-two");rejects([&]{s.recordVerifiedResult(second.id,"room-two",context(),result(),30);},"replay reused for another battle");check(s.battle(second.id).status==c::BattleStatus::Started&&!s.verifiedResult(second.id),"replay collision partially completed");
 check(s.load("test").revision==0&&s.history("test").size()==1,"M6 invented campaign credit");
}
void outcomes(){for(int n=1;n<=9;++n){c::CampaignStore s(":memory:");seed(s);auto b=started(s,"room");auto r=result();r.outcome=static_cast<c::ResultOutcome>(n);if(n!=1){r.winners.clear();r.replayId.clear();r.replayDigest.clear();r.finalTick=0;auto bad=r;bad.replayId="half";rejects([&]{s.recordVerifiedResult(b.id,"room",context(),bad,12);},"unpaired abort replay accepted");}s.recordVerifiedResult(b.id,"room",context(),r,12);check(s.verifiedResult(b.id)->outcome==r.outcome,"outcome did not roundtrip");check(s.battle(b.id).status==(n==1?c::BattleStatus::Completed:c::BattleStatus::Cancelled),"wrong outcome terminal state");check(s.load("test").revision==0,"abort changed campaign state");}}
void stale(){for(int n=0;n<2;++n){c::CampaignStore s(":memory:");seed(s);auto b=started(s,"room");if(n==0){auto old=s.load("test");s.commit("test",0,old.state,"revision change");}else{s.setAllegiance("test","alice",c::Alliance::Terror,0,12);s.setAllegiance("test","alice",c::Alliance::Honor,1,13);}bool staleTyped=false;try{s.recordVerifiedResult(b.id,"room",context(),result(),14);}catch(const c::StaleBattleError&){staleTyped=true;}check(staleTyped,"stale eligibility did not use distinct error type");auto r=result();r.outcome=c::ResultOutcome::ServerAbort;r.winners.clear();s.recordVerifiedResult(b.id,"room",context(),r,14);check(s.battle(b.id).status==c::BattleStatus::Cancelled&&s.verifiedResult(b.id)->winners.empty(),"stale abort cannot be audited");}}
void durable(const fs::path& p){bool fail=false;std::string id;{c::CampaignStore s(p,c::StoreOptions{[&]{if(fail)throw std::runtime_error("injected");}});seed(s);id=started(s,"room").id;fail=true;bool ioFailure=false;try{s.recordVerifiedResult(id,"room",context(),result(),12);}catch(const c::StaleBattleError&){throw std::runtime_error("I/O failure misclassified as stale eligibility");}catch(const std::runtime_error&){ioFailure=true;}check(ioFailure,"failure hook not reached");check(!s.verifiedResult(id)&&s.battle(id).status==c::BattleStatus::Started,"result/status rollback not atomic");{Raw raw(p);check(raw.count("SELECT count(*) FROM verified_match_results")==0&&raw.count("SELECT count(*) FROM battle_status_events")==2,"failed write left audit fragments");}}
 {c::CampaignStore s(p);check(!s.verifiedResult(id)&&s.battle(id).status==c::BattleStatus::Started,"rollback lost across restart");s.recordVerifiedResult(id,"room",context(),result(),12);}
 {c::CampaignStore s(p);auto r=s.verifiedResult(id);check(r&&r->replayId=="replay-one"&&r->replayDigest==std::string(64,'c')&&r->finalTick==1234&&r->engineBuild=="test-build","durable replay binding lost");check(s.battle(id).status==c::BattleStatus::Completed,"durable completion lost");rejects([&]{s.recordVerifiedResult(id,"room",context(),result(),13);},"restart permits duplicate");}
 {Raw raw(p);rejects([&]{raw.sql("UPDATE verified_match_results SET outcome=4");},"immutable result update allowed");rejects([&]{raw.sql("DELETE FROM verified_match_results");},"immutable result deletion allowed");}}
void migration(const fs::path& root){for(int version:{1,2,3}){auto p=root/("v"+std::to_string(version)+".sqlite");std::string id;{c::CampaignStore s(p);seed(s);auto old=s.load("test");s.commit("test",0,old.state,"old",c::BattleResult{"legacy","payload"});id=started(s,"old-room").id;}
 std::set<std::string> keep={"campaigns","campaign_events","battle_results","campaign_events_no_update","campaign_events_no_delete","battle_results_no_update","battle_results_no_delete","campaign_definition_no_update"};
 if(version>=2)for(auto n:{"campaign_participants","allegiance_events","allegiance_events_no_update","allegiance_events_no_delete","campaign_participant_identity_no_update"})keep.insert(n);
 if(version>=3)for(auto n:{"issued_battles","battle_status_events","battle_rooms","issued_battle_identity_no_update","battle_status_no_update","battle_status_no_delete","battle_rooms_no_update","battle_rooms_no_delete"})keep.insert(n);
 {Raw raw(p);sqlite3_stmt* q=nullptr;check(sqlite3_prepare_v2(raw.db,"SELECT type,name FROM sqlite_master WHERE name NOT GLOB 'sqlite_*' ORDER BY type DESC",-1,&q,nullptr)==SQLITE_OK,"schema fixture read");std::vector<std::pair<std::string,std::string>> remove;while(sqlite3_step(q)==SQLITE_ROW){std::string type=reinterpret_cast<const char*>(sqlite3_column_text(q,0)),name=reinterpret_cast<const char*>(sqlite3_column_text(q,1));if(!keep.count(name))remove.emplace_back(type,name);}sqlite3_finalize(q);for(auto& [type,name]:remove)raw.sql("DROP "+type+" \""+name+"\"");raw.sql("PRAGMA user_version="+std::to_string(version));}
 rejects([&]{c::CampaignStore s(p,c::StoreOptions{[]{throw std::runtime_error("migration fail");}});},"migration failure ignored");{Raw raw(p);check(raw.count("PRAGMA user_version")==version&&raw.count("SELECT count(*) FROM sqlite_master WHERE name='verified_match_results'")==0,"migration rollback incomplete");}
 c::CampaignStore s(p);check(s.load("test").revision==1&&s.history("test").size()==2&&s.battleResult("test","legacy")=="payload","migration lost campaign audit/result");check(bool(s.allegiance("test","alice"))==(version>=2),"migration lost/invented allegiance");if(version==3){check(s.battle(id).status==c::BattleStatus::Started&&s.battle(id).roomToken=="old-room"&&!s.verifiedResult(id),"migration lost old battle or invented result");s.recordVerifiedResult(id,"old-room",context(),result(),12);check(s.battle(id).status==c::BattleStatus::Completed,"migrated battle cannot finish");}{Raw raw(p);check(raw.count("PRAGMA user_version")==5,"migration not schema5");}
}}
}
int main(){auto root=fs::temp_directory_path()/("tak-result-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));struct Cleanup{fs::path p;~Cleanup(){std::error_code e;fs::remove_all(p,e);}}cleanup{root};try{fs::create_directories(root);validation();outcomes();stale();durable(root/"durable.sqlite");migration(root);std::cout<<"PASS: "<<checks<<" Crusades result checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
